Consider the following C program:

```c
#include <stdio.h>
int fun(int n, int *fp) {
    int t, f;
    if (n <= 1) {
        *fp = 1;
        return 1;
    }
    t = fun(n-1, fp);
    f = t + *fp;
    *fp = t;
    return f;
}
int main() {
    int x = 0;
    printf("%d\n", fun(5, &x));
    return 0;
}
```
What is the output?

